import{_ as a,o as e,c as r,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Macro-Introduction.md","filePath":"manual-zh/Macro-Introduction.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Macro-Introduction.md"};function t(d,o,i,s,p,_){return e(),r("div",null,[...o[0]||(o[0]=[c(`<h4 id="_14-2-2-introduction" tabindex="-1">14.2.2 Introduction <a class="header-anchor" href="#_14-2-2-introduction" aria-label="Permalink to &quot;14.2.2 Introduction&quot;">​</a></h4><p><code>DEFINE</code> 命令创建一个_宏_（macro），它是称为宏_主体_（body）的一段 PSPP 语法的名称。在 <code>DEFINE</code> 命令之后，语法可以通过名称任意次_调用_该宏。每次调用都将该宏的主体替换（或_展开_）到调用所在的位置，就如同主体被写在那个位置一样。</p><p>以下语法定义了一个名为 <code>!vars</code> 的宏，它展开为变量名 <code>v1 v2 v3</code>。宏的名称以‘!’开头，这对宏名是可选的。宏名后面的 <code>()</code> 是必需的：</p><pre><code>DEFINE !vars()
v1 v2 v3
!ENDDEFINE.
</code></pre><p>以下是给定上述定义后调用 <code>!vars</code> 的两种方式：</p><pre><code>DESCRIPTIVES !vars.
FREQUENCIES /VARIABLES=!vars.
</code></pre><p>通过宏展开，上述调用等价于以下内容：</p><pre><code>DESCRIPTIVES v1 v2 v3.
FREQUENCIES /VARIABLES=v1 v2 v3.
</code></pre><p><code>!vars</code> 宏展开为一个固定的主体。宏可以有更复杂的内容：</p><ul><li>宏_参数_（arguments），每当它们被命名时就被替换进主体。宏参数的值在每次调用时指定。参见 <a href="./Macro-Arguments">Macro Arguments</a>。</li><li>宏_函数_（functions），在宏被调用时展开。参见 <a href="./Macro-Functions">Macro Functions</a>。</li><li><code>!IF</code> 结构，用于条件展开。参见 <a href="./Macro-Conditional-Expansion">Macro Conditional Expansion</a>。</li><li>两种形式的 <code>!DO</code> 结构，用于遍历数值范围或记号集合。参见 <a href="./Macro-Loops">Macro Loops</a>。</li><li><code>!LET</code> 结构，用于赋值给宏变量。参见 <a href="./Macro-Variable-Assignment">Macro Variable Assignment</a>。</li></ul><p>许多与宏相关的标识符以‘!’开头，该字符通常不允许出现在标识符中。这些标识符仅保留供宏使用，这有助于避免它们与其他种类的标识符混淆。</p><p>以下各节提供关于宏语法和语义的更多细节。</p>`,12)])])}const E=a(n,[["render",t]]);export{u as __pageData,E as default};
